      id: "20261007-01",
      category: "politics",
      title: `外交部回应台湾接收美制F-16V：坚决反对美对台军售立场一贯明确`,
      summary: `针对台湾近日接收自美国采购的两架F-16V战斗机，外交部发言人表示，中方坚决反对美国向中国台湾地区出售武器的立场是一贯、明确的，将采取坚决有力措施捍卫主权和安全利益。`,
      time: "09:00",
      source: "央视新闻",
      detail: `针对台湾地区近日接收自美国采购的两架F-16V战斗机，外交部发言人在例行记者会上应询表示，中方坚决反对美国向中国台湾地区出售武器的立场是一贯、明确的。发言人指出，美方向中国台湾地区出售武器严重违反一个中国原则和中美三个联合公报特别是"八·一七"公报规定，干涉中国内政，损害中国主权和安全利益，也损害中美关系和台海和平稳定。中方敦促美方切实恪守一个中国原则，立即停止售台武器和美台军事联系，停止危险言行，以免对中美关系和台海局势造成进一步损害。中方将采取坚决有力措施，坚定捍卫自身主权和安全利益。

分析认为，对台军售是中美关系中最敏感的问题之一。此次F-16V交付正值台海局势持续受到关注之际，中方的表态延续了"坚决反对、敦促停止"的一贯立场，同时强调将采取反制措施，体现了在台湾问题上不妥协的红线意识。历史上，中方曾多次对参与对台军售的美国防务企业实施制裁，后续反制动向值得持续关注。`,
      meaning: `台湾问题是中国核心利益中的核心。美对台军售触碰红线，中方表态划明底线，反制措施可期，台海局势走向值得持续关注。`,
