      detail: "7月16日，成立世界人工智能合作组织协定签署仪式在上海举行。中共中央政治局委员、外交部长王毅出席并代表中国政府签署协定。\n\n协定明确，世界人工智能合作组织是独立的政府间国际组织，遵循《联合国宪章》宗旨，秉持共商共建共享理念，旨在促进人工智能国际合作和全球治理，确保人工智能朝着有益、安全、公平方向健康有序发展，造福全人类。\n\n总部设在中国上海。哈萨克斯坦、老挝、巴基斯坦、俄罗斯、印度尼西亚等29个国家代表签署协定，成为创始成员国。联合国秘书长古特雷斯等出席仪式。\n\n近期，《2026中国AI盛典》发布十大年度AI人物，王兴兴、王鹤等入选，蔡磊被评为“年度AI特别贡献人物”。",
